package net.zartra.gui;
import org.bukkit.entity.Player;import java.util.*;
final class MenuRefreshManager {private final ZartraGUIPlugin plugin;private final MenuManager menus;private final Map<UUID,Integer> tasks=new HashMap<UUID,Integer>();MenuRefreshManager(ZartraGUIPlugin p,MenuManager m){plugin=p;menus=m;}void start(final Player p,final MenuDefinition d,final int page){stop(p);long ticks=Math.max(20,d.refreshInterval);if(d.refreshInterval<=0)return;int id=org.bukkit.Bukkit.getScheduler().scheduleSyncRepeatingTask(plugin,new Runnable(){public void run(){if(!p.isOnline()){stop(p);return;}menus.refreshOpen(p,d,page);}},ticks,ticks);tasks.put(p.getUniqueId(),id);}void stop(Player p){Integer id=tasks.remove(p.getUniqueId());if(id!=null)org.bukkit.Bukkit.getScheduler().cancelTask(id);}void clear(){for(Integer id:tasks.values())org.bukkit.Bukkit.getScheduler().cancelTask(id);tasks.clear();}}